-- ============================================================
-- いけばな・池坊（テーマID: 17, category_id: 6）問題投入SQL
-- 全20問（難易度1〜3）
-- 選択肢対応: (ア)=0, (イ)=1, (ウ)=2, (エ)=3
-- ============================================================

INSERT INTO questions (category_id, theme_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty_level, is_premium) VALUES

(6, 17, 'いけばな（華道）の家元として世界最古と言われる「池坊（いけのぼう）」の本拠がある寺はどこか。', '東本願寺', '六角堂（頂法寺）', '知恩院', '東福寺', 1, '池坊の本拠は京都市中京区にある六角堂（頂法寺、ろっかくどう）です。聖徳太子が創建したとされるこの寺の住職が「池坊」の名称の由来で、寺の池のほとりに坊（住居）があったことから名付けられました。', 1, false),
(6, 17, '池坊の流祖（創始者）とされる人物はだれか。', '池坊専応', '池坊専慶', '池坊専好', '池坊専永', 1, '池坊の流祖とされるのは室町時代の僧・池坊専慶（いけのぼうせんけい、15世紀）です。1462年の記録に専慶が花を立てたことが記され、これがいけばなの最古の記録のひとつとされています。', 1, false),
(6, 17, '池坊が確立した「立花（りっか）」の特徴として正しいのはどれか。', '自然の野山を再現した自由な形式', '7本以上の枝・花材で構成する厳格な様式美', '花一本だけを器に差すシンプルな形式', '西洋の花材を中心に使う近代的様式', 1, '立花（りっか）は7つの役枝（やくえだ）をもとに構成される池坊の最も古い様式で、天地・陰陽の宇宙観を表します。大型で厳格な美しさが特徴で、池坊が完成させたいけばなの最高の様式とされています。', 1, false),
(6, 17, 'いけばなの三大流派のうち池坊以外の二流派として正しいのはどれか。', '未生流・古流', '草月流・小原流', '龍生派・嵯峨御流', '志甫流・宏道流', 1, 'いけばな三大流派は「池坊（いけのぼう）」「草月流（そうげつりゅう）」「小原流（おはらりゅう）」とされています。草月流は勅使河原蒼風、小原流は小原雲心が創始した近代的な流派です。', 1, false),
(6, 17, 'いけばなの形式「生花（しょうか）」の特徴として正しいのはどれか。', '庭の花をそのまま持ち込む自然なスタイル', '真（しん）・副（そえ）・体（たい）の三才で構成する', '西洋の花束様式に近い', '格式を持たない自由な表現', 1, '生花（しょうか/せいか）は池坊で江戸時代に発展した様式で、「真（しん）・副（そえ）・体（たい）」の三才（天・地・人）を基本に花材を組み合わせます。立花より小型で、自然の風情を表現します。', 2, false),
(6, 17, '「自由花（じゆうか）」はいつ頃から生まれた様式か。', '平安時代', '江戸時代', '明治・大正以降', '昭和後期', 2, '自由花は明治・大正時代以降、西洋花材の流入や文明開化の影響を受けて形式的な制約を取り除いた自由な表現様式として広まりました。現代いけばなの主流となっています。', 2, false),
(6, 17, '池坊の家元が代々住職を務める六角堂（頂法寺）の本堂の形が六角形になっている理由として伝わるものはどれか。', '聖徳太子の夢のお告げ', '地形的な理由', '風水（四神相応）の考え', '鎌倉時代の改築', 0, '六角堂の六角形の本堂は、聖徳太子が仏像を木に掛けて一夜を明かしたとき、夢で六角のお堂を建てよとお告げがあったためと伝わります。現在の建物は1877年に再建されたものです。', 2, false),
(6, 17, '豊臣秀吉時代に活躍し「天下一の花師」とも呼ばれた池坊の大家はだれか。', '池坊専慶', '池坊専応', '池坊専好（初代）', '池坊専永', 2, '池坊専好（初代、いけのぼうせんこう、?〜1621年）は安土桃山時代〜江戸初期の池坊を代表する花師で、豊臣秀吉の御前でも花を立て「天下一の花師」とも呼ばれました。立花の名品を残しています。', 2, false),
(6, 17, '池坊が記した最古のいけばなの理論書「池坊専応口伝（いけのぼうせんおうくでん）」が書かれたのはいつか。', '1247年（宝治元年）', '1445年（文安2年）', '1542年（天文11年）', '1680年（延宝8年）', 2, '「池坊専応口伝」は1542年（天文11年）に専応が著したいけばなの理論書です。花を立てる心得・姿勢・自然の理を記したもので、いけばなを芸道として確立する重要な文献とされています。', 3, false),
(6, 17, '「立花（りっか）」の七つの役枝のうち最も高く直立する主役の枝を何と呼ぶか。', '副（そえ）', '体（たい）', '真（しん）', '見越（みこし）', 2, '「真（しん）」は立花の最も高く中心に位置する役枝で、天（宇宙・精神）を表します。真を中心として副・体・流し・見越し・控え・胴の7つの役枝が構成されています。', 3, false),
(6, 17, '小原流のいけばなを創始した人物はだれか。', '勅使河原蒼風', '小原雲心', '上田桑鳩', '中山文甫', 1, '小原流は小原雲心（おはらうんしん、1861〜1916年）が創始した流派です。西洋の花材を低い容器（水盤）に活ける「盛り花（もりばな）」の様式を確立し、近代いけばなに大きな影響を与えました。', 2, false),
(6, 17, '草月流のいけばなを創始した人物はだれか。', '勅使河原蒼風', '小原雲心', '池坊専月', '中川幸夫', 0, '草月流は勅使河原蒼風（てしがわらそうふう、1900〜1979年）が1927年に創始した流派です。「花は野にあるように」を理念に、自由で前衛的な表現を推進し、現代いけばなの革新に大きく貢献しました。', 2, false),
(6, 17, '現在の池坊家元は何代目か（2024年時点）。', '43代', '45代', '47代', '49代', 2, '現在（2024年時点）の池坊家元は池坊専永（いけのぼうせんえい）であり、47代家元です。1954年より家元を務めており、世界最古のいけばな流派を率いています。', 3, false),
(6, 17, '嵯峨天皇が始めたとされ「嵯峨御流（さがごりゅう）」の本拠はどこか。', '嵯峨天皇陵', '大覚寺（嵯峨御所）', '仁和寺', '天龍寺', 1, '嵯峨御流（さがごりゅう）は嵯峨天皇が始めたとされるいけばなの流派で、大覚寺（だいかくじ、嵯峨御所）を本拠としています。嵯峨天皇が大沢池（おおさわのいけ）の花を手折って花を活けたことが起源とされています。', 2, false),
(6, 17, '「盛り花（もりばな）」を広めた流派はどれか。', '池坊', '草月流', '小原流', '嵯峨御流', 2, '盛り花（もりばな）は小原雲心が創始した小原流が広めた様式で、水盤（すいばん）と呼ばれる浅く広い器に花を盛るように活けます。西洋の花材を生かしやすく、現在最も普及した形式のひとつです。', 1, false),
(6, 17, '六角堂（頂法寺）の境内にある「へそ石」の意味として伝わるのはどれか。', '京都の中心（へそ）を示す石', '聖徳太子が座った石', '縁結びのパワースポット', '厄除けの石', 0, '六角堂境内にある「へそ石（臍石）」は京都の中心（へそ）を示すと伝えられています。平安京の設計にあたって京の中心とされた場所とも言われ、現在もパワースポットとして参拝者が訪れます。', 2, false),
(6, 17, '「未生流（みしょうりゅう）」のいけばなを創始した人物はだれか。', '未生斎一甫', '吾妻流主', '池坊専月', '小原雲心', 0, '未生流（みしょうりゅう）は江戸時代後期の未生斎一甫（みしょうさいいっぽ）が大阪で創始した流派です。天・地・人を表す三角形の構成理論（未生理論）が特徴で、全国に広まった有力な流派のひとつです。', 3, false),
(6, 17, '池坊が毎年京都で行う大規模ないけばな展覧会の名称はどれか。', '池坊花展', '京都いけばなサミット', '池坊全国華道展', '六角堂花まつり', 2, '池坊は毎年秋に京都で「池坊全国華道展」を開催しており、全国の池坊会員が作品を出品する大規模な展覧会です。また「池坊いけばな展」も各地で行われています。', 3, false),
(6, 17, '花道（華道）で「花器（かき）」の種類として「つるかご」や「竹筒」が使われる様式はどれか。', '立花（りっか）', '生花（しょうか）', '自由花（じゆうか）', '格花（かくばな）', 2, '自由花（じゆうか）では花器の制約がなく、つるかご・竹筒・ガラス・金属・石など多様な素材の容器が使われます。表現したいテーマや花材に合わせて花器も自由に選ぶのが自由花の特徴です。', 2, false),
(6, 17, '六角堂（頂法寺）の本尊はどれか。', '如意輪観音', '如来', '薬師如来', '阿弥陀如来', 0, '六角堂の本尊は如意輪観音（にょいりんかんのん）で、聖徳太子作と伝わります。六角堂は現在も池坊の本拠として、また縁結びの観音様として参拝者に親しまれています。', 2, false);

